using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

// Register the chat client via MEAI abstraction
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAI.Chat.ChatClient(modelId, apiKey).AsIChatClient()));

builder.Services.AddSingleton<ResearchNotes>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<ResearchNotes>();

// Define tools the agent can use
var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            // Simulated web search — replace with a real search API (Bing, Google, etc.)
            Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
            return $"""
                Search results for "{query}":
                1. "{query}" - Wikipedia overview: A comprehensive introduction covering key concepts and history.
                2. Recent advances in {query} - Nature 2025: Discusses latest breakthroughs and practical applications.
                3. {query} explained simply - Educational resource with examples and diagrams.
                """;
        },
        "search_web",
        "Searches the web for information on a given query and returns relevant results."),

    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title,
         [Description("Content of the note")] string content) =>
        {
            notes.Add(title, content);
            Console.WriteLine($"  [Tool] Note saved: \"{title}\"");
            return $"Note '{title}' saved successfully.";
        },
        "save_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () =>
        {
            var allNotes = notes.GetAll();
            Console.WriteLine($"  [Tool] Retrieved {allNotes.Count} note(s).");
            return allNotes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", allNotes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all saved research notes."),
};

// Configure the agent
var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Researching topic: \"{topic}\"\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to research a topic thoroughly by:
        1. Searching the web for relevant information (make 2-3 searches with different queries)
        2. Saving key findings as notes using the note-taking tool
        3. After gathering enough information, retrieve your notes and produce a final summary

        Be methodical: search, take notes on findings, then summarize.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = tools,
};

// Run the agent loop via Microsoft.Agents.AI ChatClientAgent
var agent = new ChatClientAgent(chatClient, "ResearchAgent",
    "Researches topics by searching the web and taking notes.");

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Instructions = messages[0].Text,
};

Console.WriteLine("--- Agent working ---\n");

var history = new List<ChatMessage> { messages[1] };
string? finalResponse = null;

await foreach (var message in agent.InvokeStreamingAsync(
    history, options, invokeOptions))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        finalResponse = message.Text;
    }
}

Console.WriteLine("\n--- Research Summary ---\n");
Console.WriteLine(finalResponse ?? "No summary generated.");

if (notes.GetAll().Count > 0)
{
    Console.WriteLine("\n--- Saved Notes ---\n");
    foreach (var note in notes.GetAll())
    {
        Console.WriteLine($"• {note.Title}");
    }
}

// Note-taking service
public class ResearchNotes
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void Add(string title, string content) => _notes.Add((title, content));

    public IReadOnlyList<(string Title, string Content)> GetAll() => _notes.AsReadOnly();
}

