    "Researches topics by searching the web and taking notes.");

var invokeOptions = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Instructions = messages[0].Text,
};

Console.WriteLine("--- Agent working ---\n");

var history = new List<ChatMessage> { messages[1] };
